#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-03
# Tracing-tier campaign ("certainty vs dose", notes/full_paper_todo.md §E): the same Autoware replay at
# FISH_TRACE_TIER = min / default / max (+ an untraced baseline), identical kernel session, shim and pinning.
# Host state expected (abort otherwise): scripts/host_perf_mode.sh split  → SMT off, turbo off, performance
# governor; app on P-cores 0,2,4,6,8,10, observer on E-cores 12-17.
# Usage: REPS=3 IMG=autoware-dev-trt-a1000-fishwait17:latest scripts/campaign_tiers.sh
set -euo pipefail
cd "$(dirname "$0")/.."
REPS=${REPS:-3}; IMG=${IMG:-autoware-dev-trt-a1000-fishwait17:latest}; RATE=${RATE:-0.5}
TIERS=${TIERS:-"min default max"}
stamp() { echo "[tiers $(date +%T)] $*"; }
# --- preflight: host in split mode?
ST=$(bash scripts/host_perf_mode.sh status 2>/dev/null)
echo "$ST" | grep -q "smt             : off" || { stamp "ABORT: SMT is on — run: sudo bash scripts/host_perf_mode.sh split"; exit 2; }
echo "$ST" | grep -q "governor/epp    : performance" || { stamp "ABORT: governor is not performance — run: sudo bash scripts/host_perf_mode.sh split"; exit 2; }
ip -o link show lo | grep -q MULTICAST || { stamp "ABORT: lo multicast is OFF"; exit 2; }
lsmod | grep -q lttng_tracer || stamp "WARNING: lttng-modules not loaded yet (the first traced run loads them)"
export FISH_APP_CPUS=0,2,4,6,8,10 FISH_OBS_CPUS=12-17 FISH_CDDS_XML=1 FISH_KERNEL_SCHED=1 FISH_PER_INSTANCE=true FISH_EVENT_COUNT=0
OUT=$HOME/fish_traces/campaign_tiers_$(date +%Y%m%d_%H%M%S); mkdir -p "$OUT"
stamp "campaign → $OUT (image=$IMG reps=$REPS tiers=$TIERS)"; echo "$ST" > "$OUT/host_perf_mode_before.txt"
# --- baseline once (untraced), then one traced campaign per tier (nsys mode = LTTng + CUPTI/nsys)
stamp "baseline x$REPS"; REPS=$REPS MODES=baseline IMG=$IMG RATE=$RATE bash scripts/autoware_runs/run_overhead_modes.sh 2>&1 | tee "$OUT/baseline.log" | grep "campaign →\|complete\|ERROR" || true
for T in $TIERS; do
  stamp "tier $T x$REPS"
  FISH_TRACE_TIER=$T REPS=$REPS MODES=nsys IMG=$IMG RATE=$RATE bash scripts/autoware_runs/run_overhead_modes.sh 2>&1 | tee "$OUT/tier_$T.log" | grep "campaign →\|complete\|ERROR" || true
  bash scripts/host_perf_mode.sh status 2>/dev/null | grep -E "throttle|TCPU" >> "$OUT/host_perf_mode_after.txt" || true
done
stamp "done. Campaign dirs:"; grep -h "campaign →" "$OUT"/*.log | sed 's/.*→ //' | cut -d' ' -f1 | tee "$OUT/campaign_dirs.txt"
stamp "next: for each session: ingest_pg → model_improved_pg (provenance log line) → ksched_split; compare analyze_overhead tables and the 'provenance of derived quantities' counts across tiers"
